#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{corpus,receive,source,grant,observe,drain,central_fragment,project_record,denied_axes};
struct Latitude;
impl SingleFieldPath for Latitude{type Scalar=f64;type Branch=StateSite;type Output=SiteBranchOutput;fn branch(o:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,Self::Branch>{o.project(0,|s|s.model.identity.get().site.get())}fn read(b:&Self::Branch)->f64{b.latitude_deg}fn select(b:&mut Self::Branch)->&mut f64{&mut b.latitude_deg}fn valid(v:f64)->bool{v.is_finite()&&(-90.0..=90.0).contains(&v)}fn output()->Self::Output{SiteBranchOutput::new()}}
struct StartDay;
impl SingleFieldPath for StartDay{type Scalar=u8;type Branch=crate::calendar::RunPeriod;type Output=RunPeriodBranchOutput;fn branch(o:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,Self::Branch>{o.project(0,|s|s.model.identity.get().run_period.get())}fn read(b:&Self::Branch)->u8{b.start_day}fn select(b:&mut Self::Branch)->&mut u8{&mut b.start_day}fn valid(v:u8)->bool{(1..=31).contains(&v)}fn valid_context(v:u8,b:&Self::Branch)->bool{let mut period=*b;period.start_day=v;period.is_interval()}fn output()->Self::Output{RunPeriodBranchOutput::new()}}
fn run<S:SingleFieldPath>(case:&serde_json::Value,cuts:&[serde_json::Value])where S::Scalar:semio_framework_value_native_owned::native_decoding::NativeReceive<semio_framework_value::DslValue>+std::fmt::Debug{
 let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();let branch=case["branch"].as_str().unwrap();let field=case["field"].as_str().unwrap();if let Some(context)=case.get("context"){document["model"][branch]=context.clone();}document["model"][branch][field]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let input=source(receive::<S::Scalar>(&case["value"]));assert!(size_of::<SingleFieldPreparation<S>>()<=4096);
 for cut in std::iter::once(None).chain(cuts.iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut owner=SingleFieldPreparation::<S>::new();let mut turns=0;while !owner.ready()&&cut.is_none_or(|c|turns<c){let d=owner.demand(input.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(input.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(input.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.advance(input.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;assert!(turns<10000);}
  if cut.is_none(){assert_eq!(owner.outcome().unwrap().as_str(),case["outcome"].as_str().unwrap());if owner.outcome()==Some(RowOutcome::Changed){let(diff,_)=owner.take(grant(owner.take_demand().unwrap())).unwrap().unwrap();let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));let post=source(post);assert_eq!(S::read(S::branch(post.borrow().project(0,|p|p.as_ref())).get()),receive::<S::Scalar>(&case["after"]));assert_eq!(post.borrow().get().model.geometry.identity(),original.borrow().get().model.geometry.identity());assert_eq!(post.borrow().get().model.identity.get().name.identity(),original.borrow().get().model.identity.get().name.identity());let(inverse,_)=owner.take_inverse(grant(owner.inverse_demand().unwrap())).unwrap().unwrap();assert_eq!(inverse,receive::<S::Scalar>(&case["before"]));drain(post);drain(diff);}}
  owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(S::read(S::branch(original.borrow()).get()),receive::<S::Scalar>(&case["before"]));
 }drain(input);drain(original);
}
