fn native_singleton_site_and_calendar_fields_preserve_context_original_inverse_and_every_cancelled_prefix(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){match case["branch"].as_str().unwrap(){"site"=>run::<Latitude>(case,law["cancelAt"].as_array().unwrap()),"run_period"=>run::<StartDay>(case,law["cancelAt"].as_array().unwrap()),_=>panic!("authored singleton branch")}}}

#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
struct LatitudeOperation{value:f64}
impl protocol::Mutation<EnergyModelSnapshot> for LatitudeOperation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("fixture exercises only retained semantic ports")}}
impl super::SingleLeafSpec<LatitudeOperation,LatitudeOperation> for Latitude{
 const INVALID:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Fatal,code:"mutation.invariant",message:"A zone volume must be positive and finite."};
 const UNCHANGED:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Warning,code:"mutation.no-op",message:"The zone already has this volume."};
 fn input(payload:RetainedCloneRef<'_,LatitudeOperation>)->RetainedCloneRef<'_,f64>{payload.project(0,|p|&p.value)}
 fn inverse(payload:RetainedCloneRef<'_,LatitudeOperation>,value:f64)->LatitudeOperation{LatitudeOperation{value}}
}
#[test]
fn shared_native_singleton_leaf_preserves_empty_targets_and_original_inverse_factory(){
 use super::SingleLeafPreparation;
 use protocol::mutation::retained::{RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
 type Owner=SingleLeafPreparation<LatitudeOperation,LatitudeOperation,Latitude>;
 assert!(size_of::<Owner>()<=4096);
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter().filter(|row|row["branch"]=="site"){
  let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();document["model"]["site"]["latitude_deg"]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let payload=source(LatitudeOperation{value:case["value"].as_f64().unwrap()});
  for cutoff in std::iter::once(None).chain((0..200).map(Some)){
   let mut owner=Owner::new();let mut ready=false;for _ in 0..cutoff.unwrap_or(10000){let d=owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}
   let mut diff=None;let mut inverse=None;if ready{match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert!(case["outcome"]=="invalid");assert!(messages[0].target.is_empty());close_messages(messages);},RetainedMutationDecision::Admitted(value,messages)=>{assert!(case["outcome"]=="changed"||case["outcome"]=="no-op");assert_eq!(messages.len(),usize::from(case["outcome"]=="no-op"));close_messages(messages);let value=source(value);for _ in 0..cutoff.unwrap_or(10000){let g=grant(owner.inverse_demand(payload.borrow(),original.borrow(),value.borrow(),4096).unwrap());let(s,h)=observe(||owner.inverse(payload.borrow(),original.borrow(),value.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){if cutoff.is_none(){let rows=owner.take_inverse();assert_eq!(rows.len(),usize::from(case["outcome"]=="changed"));if let Some(row)=rows.first(){assert_eq!(row.value,case["before"].as_f64().unwrap());}inverse=Some(rows);}break;}}diff=Some(value);}}}else{assert!(cutoff.is_some());}
   let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<LatitudeOperation>::default();let context=RetainedMutationCloseContext{mutations:&factory};owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(context,4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(context,4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(diff)=diff{drain(diff);}if let Some(inverse)=inverse{drain(inverse);}
  }drain(payload);drain(original);
 }
}
fn close_messages(messages:Vec<protocol::MutationMessage>){let mut owner=protocol::MutationMessageLedgerRetirement::new(String::new(),messages);for _ in 0..10000{if owner.terminal_is_empty(){return;}let d=semio_framework_value::RetirementDemand{copy_bytes:owner.next_copy_byte_demand(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};let g=grant(d);let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}panic!("native scalar diagnostic close stalled");}
